-- ═══════════════════════════════════════════════════════════════
-- GEMA Seed v1: Lieferanten + Produkte + Armaturen-Katalog
-- Reale Herstellerdaten (Web-Recherche 2026-07-14) — ALLE Produkte/Armaturen
-- bewusst status='nicht_verifiziert' (Verifizierungs-Workflow-Test).
--
-- AUSFÜHREN: Supabase Dashboard → SQL Editor → dieses File einfügen → Run.
-- Idempotent: ON CONFLICT DO NOTHING — bereits vorhandene Records
-- (z.B. inzwischen verifizierte) werden NIE überschrieben.
-- Erzeugt von scripts/lieferanten_seed_gen.mjs — dort ändern, nicht hier.
--
-- Rollback: supabase/gema_lieferanten_seed_rollback.sql
-- ═══════════════════════════════════════════════════════════════

on conflict (module_key, data_key) do nothing;

-- Kontrolle: sollte 42 Zeilen liefern
select module_key, count(*) from public.gema_data where data_key like 'lieferant:lief_seed_%' or data_key like 'produkt:prod_seed_%' or data_key like 'arm:arm_seed_%' group by module_key;
